        internal static DeviceCatalogEntry WithAdditionalSources(DeviceCatalogEntry entry)
        {
            DeviceCatalogSource[] extra;
            switch (entry.Id)
            {
                case "pulsar-power":
                    extra = new[] { new DeviceCatalogSource("OpenMouse Atlantis/Scyrox/VGN report08 facts", "https://github.com/OpenMouse-Project/mouse-protocol/blob/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/lamzu/atlantis.ts", "AGPL-3.0-or-later") }; break;
                case "lamzu-maya-x":
                    extra = new[] { new DeviceCatalogSource("OpenMouse Lamzu/CRDRAKO/LunaFury/Vancer/AttackShark/RAWM facts", "https://github.com/OpenMouse-Project/mouse-protocol/blob/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/lamzu/index.ts", "AGPL-3.0-or-later") }; break;
                case "asus-mouse":
                    extra = new[] { new DeviceCatalogSource("OpenMouse ASUS battery codec facts", "https://github.com/OpenMouse-Project/mouse-protocol/tree/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/asus", "AGPL-3.0-or-later") }; break;
                case "gwolves-old":
                    extra = new[] { new DeviceCatalogSource("OpenMouse G-Wolves XVI battery protocol", "https://github.com/OpenMouse-Project/mouse-protocol/tree/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/drivers/gwolves/xvi", "AGPL-3.0-or-later") }; break;
                case "gwolves-new":
                    extra = new[] { new DeviceCatalogSource("OpenMouse G-Wolves XVI:1 protocol and descriptor fixtures", "https://github.com/OpenMouse-Project/mouse-protocol/tree/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/drivers/gwolves/xvi-new", "AGPL-3.0-or-later") }; break;
                case "mchose-g7":
                    extra = new[] { new DeviceCatalogSource("OpenMouse K-snake battery codec", "https://github.com/OpenMouse-Project/mouse-protocol/tree/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/ksnake", "AGPL-3.0-or-later") }; break;
                case "wlmouse-feature":
                    extra = new[] { new DeviceCatalogSource("OpenMouse WLmouse exact runtime table", "https://github.com/OpenMouse-Project/mouse-protocol/blob/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/drivers/vendors.ts", "AGPL-3.0-or-later") }; break;
                case "mchose-realtek":
                    extra = new[] { new DeviceCatalogSource("OpenMouse MCHOSE V2 link IDs", "https://github.com/OpenMouse-Project/mouse-protocol/blob/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/mchose/index.ts", "AGPL-3.0-or-later") }; break;
                case "razer-mouse":
                    extra = new[] { new DeviceCatalogSource("OpenMouse Razer exact device/transaction facts", "https://github.com/OpenMouse-Project/mouse-protocol/blob/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/razer/devices.ts", "AGPL-3.0-or-later"), new DeviceCatalogSource("OpenRazer protocol provenance already credited by existing family", "https://github.com/openrazer/openrazer", "GPL-2.0-or-later") }; break;
                case "logitech-hidpp":
                    extra = new[] { new DeviceCatalogSource("OpenMouse HID++ ADC measurement facts", "https://github.com/OpenMouse-Project/mouse-protocol/blob/b62a1cce2b63698ac00595efdb0067ecd54e34a0/src/drivers/logitech/hidpp.ts", "AGPL-3.0-or-later") }; break;
                default: return entry;
            }
            var commentKey = entry.CommentsKey;
            switch (entry.Id)
            {
                case "razer-mouse": commentKey = "devicelist.comment.mixed"; break;
                case "logitech-hidpp": commentKey = "devicelist.comment.logitechvoltage"; break;
            }
            return new DeviceCatalogEntry(entry.Id, entry.Name, entry.Connection, commentKey,
                entry.Sources.Concat(extra).GroupBy(source => source.Url).Select(group => group.First()).ToArray());
        }
